import{_ as e,o as l,c as d,a0 as a}from"./chunks/framework.DqMqoJl9.js";const y=JSON.parse('{"title":"05 元素嘉当矩阵参数化设计","description":"","frontmatter":{},"headers":[],"relativePath":"D039_元素嘉当矩阵参数化设计.md","filePath":"D039_元素嘉当矩阵参数化设计.md"}'),n={name:"D039_元素嘉当矩阵参数化设计.md"};function r(i,t,s,o,h,x){return l(),d("div",null,[...t[0]||(t[0]=[a('<div><h1 id="_05-元素嘉当矩阵参数化设计" tabindex="-1">05 元素嘉当矩阵参数化设计 <a class="header-anchor" href="#_05-元素嘉当矩阵参数化设计" aria-label="Permalink to &quot;05 元素嘉当矩阵参数化设计&quot;">​</a></h1><blockquote><p>嘉当矩阵参数化架构，使理论变动可方便跟进</p></blockquote><hr><h2 id="_1-嘉当矩阵的固定与可变" tabindex="-1">1. 嘉当矩阵的固定与可变 <a class="header-anchor" href="#_1-嘉当矩阵的固定与可变" aria-label="Permalink to &quot;1. 嘉当矩阵的固定与可变&quot;">​</a></h2><p>**A₄ 矩阵固定**（所有元素共享，SU(5) 群论嘉当矩阵）：</p><p>$$A_4 = \\begin{pmatrix} 2 & -1 & 0 & 0 \\\\ -1 & 2 & -1 & 0 \\\\ 0 & -1 & 2 & -1 \\\\ 0 & 0 & -1 & 2 \\end{pmatrix}$$</p><p>**元素嘉当矩阵因元素而异**，由三个参数决定：</p><table tabindex="0"><thead><tr><th style="text-align:left;">参数</th><th style="text-align:center;">符号</th><th style="text-align:left;">来源</th><th style="text-align:left;">影响</th></tr></thead><tbody><tr><td style="text-align:left;">原子序数</td><td style="text-align:center;">Z</td><td style="text-align:left;">实验</td><td style="text-align:left;">质子扇区：Z 个 A₄ 块</td></tr><tr><td style="text-align:left;">中子数</td><td style="text-align:center;">N</td><td style="text-align:left;">A−Z</td><td style="text-align:left;">中子扇区：N 个缺陷块</td></tr><tr><td style="text-align:left;">中子缺陷参数</td><td style="text-align:center;">δ(N)</td><td style="text-align:left;">CQM 公式</td><td style="text-align:left;">中子扇区缺陷程度</td></tr></tbody></table><p>$$\\mathcal{C}_{\\text{element}}(Z, N, \\delta) = \\bigoplus_{i=1}^{Z} A_4 \\oplus \\bigoplus_{j=1}^{N} C_n(\\delta_j)$$</p><p>其中 $C_n(\\delta)$ 为 $A_4$ 的 $\\alpha_4$ 末端非对角元缺陷：$(3,4)/(4,3)$ 元从 $-1$ 变为 $-\\delta$，$\\det C_n = 8 - 3\\delta^2$。</p><p>**示例**：氢 (Z=1,N=0) → 4×4 纯 A₄；氦 (Z=2,N=2) → 16×16；镧 (Z=57,N=82) → 556×556。</p><hr><h2 id="_2-三层分离架构" tabindex="-1">2. 三层分离架构 <a class="header-anchor" href="#_2-三层分离架构" aria-label="Permalink to &quot;2. 三层分离架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">层</th><th style="text-align:left;">内容</th><th style="text-align:left;">变动频率</th></tr></thead><tbody><tr><td style="text-align:left;">**第1层 理论核心**</td><td style="text-align:left;">A₄ 矩阵、本征值、谱间隙、BCS 常数、相变量子 $☯$</td><td style="text-align:left;">理论修订时</td></tr><tr><td style="text-align:left;">**第2层 建模选择**</td><td style="text-align:left;">缺陷位置、δ(N) 函数形式、耦合模型</td><td style="text-align:left;">理论调整时</td></tr><tr><td style="text-align:left;">**第3层 元素数据**</td><td style="text-align:left;">Z、同位素、电负性、半径等实验量</td><td style="text-align:left;">实验更新时</td></tr></tbody></table><p>**理论固定量**（Lean 形式化验证）：A₄ 本征值 $\\lambda_k = 2-2\\cos(k\\pi/5)$、谱间隙 $(3-\\sqrt{5})/2 \\approx 0.382$、BCS 前因子 $2e^\\gamma/\\pi \\approx 1.1339$、普适能隙比 $2\\pi e^{-\\gamma} \\approx 3.5278$、相变量子 $☯ = 0.02309570897$。</p><p>**理论可变量**（建模选择）：δ(N) 函数形式（当前线性 $\\delta_0(1-\\beta_\\delta\\Delta N/N_{\\text{ref}})$）、δ₀ 基础缺陷、$\\beta_\\delta$ 缺陷斜率、质子扇区修正、跨元素耦合模型。</p><hr><h2 id="_3-理论变动的跟进" tabindex="-1">3. 理论变动的跟进 <a class="header-anchor" href="#_3-理论变动的跟进" aria-label="Permalink to &quot;3. 理论变动的跟进&quot;">​</a></h2><p>理论变动**只改配置文件** <code>cqm_theory_config.json</code>（第1+2层），无需修改 118 个元素文件（第3层仅含实验数据）。</p><table tabindex="0"><thead><tr><th style="text-align:left;">变动场景</th><th style="text-align:left;">修改对象</th></tr></thead><tbody><tr><td style="text-align:left;">缺陷位置变更</td><td style="text-align:left;">配置 <code>defect_mode.positions</code></td></tr><tr><td style="text-align:left;">δ(N) 函数形式变更</td><td style="text-align:left;">配置 <code>neutron_defect_function</code></td></tr><tr><td style="text-align:left;">质子扇区加修正</td><td style="text-align:left;">配置 <code>proton_sector_model</code></td></tr><tr><td style="text-align:left;">A₄ 本身被修正</td><td style="text-align:left;">配置 <code>fixed_constants</code></td></tr><tr><td style="text-align:left;">元素特异覆盖</td><td style="text-align:left;">配置 <code>element_overrides</code></td></tr></tbody></table><hr><h2 id="_4-元素文件生成策略" tabindex="-1">4. 元素文件生成策略 <a class="header-anchor" href="#_4-元素文件生成策略" aria-label="Permalink to &quot;4. 元素文件生成策略&quot;">​</a></h2><p>118 元素的实验数据从公开数据库（NIST/NUBASE）批量导入，理论参数由配置统一管理，不逐个手写。元素 JSON 仅含实验数据，不包含 <code>cqm_parameters</code> 字段。</p><table tabindex="0"><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:center;">元素数</th><th style="text-align:left;">覆盖</th></tr></thead><tbody><tr><td style="text-align:left;">MVP</td><td style="text-align:center;">~20</td><td style="text-align:left;">主要超导体系</td></tr><tr><td style="text-align:left;">v0.2</td><td style="text-align:center;">~60</td><td style="text-align:left;">主族 + 3d/4d 过渡族</td></tr><tr><td style="text-align:left;">v0.5</td><td style="text-align:center;">118</td><td style="text-align:left;">全部元素</td></tr></tbody></table><hr></div>',1)])])}const _=e(n,[["render",r]]);export{y as __pageData,_ as default};
